-- 3. Verifikasi jumlah data inventaris yang berhasil masuk per gedung
SELECT building AS gedung, COUNT(*) AS jumlah_aset, SUM(capacity) AS total_unit_barang
FROM assets
WHERE asset_type = 'INVENTARIS'
GROUP BY building
ORDER BY building;
